import "./GalaxieViewLogo.scss";

const GalaxieIcon = () => (
  <svg
    viewBox="0 0 48 48"
    fill="none"
    xmlns="http://www.w3.org/2000/svg"
    className="GalaxieViewLogo-icon"
  >
    {/* Outer glow ring */}
    <defs>
      <radialGradient id="planetGlow" cx="50%" cy="50%" r="50%">
        <stop offset="0%" stopColor="#8b5cf6" stopOpacity="0.8" />
        <stop offset="50%" stopColor="#6366f1" stopOpacity="0.4" />
        <stop offset="100%" stopColor="#4f46e5" stopOpacity="0" />
      </radialGradient>
      <linearGradient id="planetSurface" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#a78bfa" />
        <stop offset="50%" stopColor="#8b5cf6" />
        <stop offset="100%" stopColor="#6366f1" />
      </linearGradient>
      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
        <feGaussianBlur stdDeviation="2" result="coloredBlur" />
        <feMerge>
          <feMergeNode in="coloredBlur" />
          <feMergeNode in="SourceGraphic" />
        </feMerge>
      </filter>
    </defs>

    {/* Background glow */}
    <circle cx="24" cy="24" r="20" fill="url(#planetGlow)" />

    {/* Main planet */}
    <circle
      cx="24"
      cy="24"
      r="14"
      fill="url(#planetSurface)"
      filter="url(#glow)"
    />

    {/* Planet highlight */}
    <ellipse
      cx="20"
      cy="20"
      rx="6"
      ry="4"
      fill="white"
      fillOpacity="0.3"
      transform="rotate(-30 20 20)"
    />

    {/* Orbital ring */}
    <ellipse
      cx="24"
      cy="24"
      rx="22"
      ry="8"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeOpacity="0.6"
      transform="rotate(-20 24 24)"
    />

    {/* Small orbiting moon */}
    <circle cx="40" cy="18" r="3" fill="currentColor" fillOpacity="0.8" />

    {/* Stars */}
    <circle cx="8" cy="10" r="1" fill="currentColor" fillOpacity="0.6" />
    <circle cx="42" cy="36" r="1.2" fill="currentColor" fillOpacity="0.5" />
    <circle cx="6" cy="34" r="0.8" fill="currentColor" fillOpacity="0.4" />
  </svg>
);

const GalaxieText = () => (
  <svg
    viewBox="0 0 280 40"
    xmlns="http://www.w3.org/2000/svg"
    fill="none"
    className="GalaxieViewLogo-text"
  >
    <defs>
      <linearGradient id="textGradient" x1="0%" y1="0%" x2="100%" y2="0%">
        <stop offset="0%" stopColor="#a78bfa" />
        <stop offset="50%" stopColor="#8b5cf6" />
        <stop offset="100%" stopColor="#6366f1" />
      </linearGradient>
    </defs>
    <text
      x="0"
      y="30"
      fontFamily="'Segoe UI', system-ui, -apple-system, sans-serif"
      fontSize="28"
      fontWeight="600"
      fill="url(#textGradient)"
      letterSpacing="-0.5"
    >
      Galaxie View
    </text>
  </svg>
);

type LogoSize = "xs" | "small" | "normal" | "large" | "custom" | "mobile";

interface LogoProps {
  size?: LogoSize;
  withText?: boolean;
  style?: React.CSSProperties;
  isNotLink?: boolean;
}

export const GalaxieViewLogo = ({
  style,
  size = "small",
  withText,
}: LogoProps) => {
  return (
    <div className={`GalaxieViewLogo is-${size}`} style={style}>
      <GalaxieIcon />
      {withText && <GalaxieText />}
    </div>
  );
};

// Export alias for compatibility
export const ExcalidrawLogo = GalaxieViewLogo;
