import React, { useState, useEffect } from "react";

import {
  GALAXIE_THEMES,
  getAllGalaxieThemes,
  getStoredGalaxieTheme,
  applyGalaxieTheme,
} from "./themes";

import type { GalaxieThemeId, GalaxieTheme } from "./themes";

import "./GalaxieThemePicker.scss";

interface GalaxieThemePickerProps {
  onChange?: (themeId: GalaxieThemeId) => void;
  compact?: boolean;
}

export const GalaxieThemePicker: React.FC<GalaxieThemePickerProps> = ({
  onChange,
  compact = false,
}) => {
  const [currentTheme, setCurrentTheme] = useState<GalaxieThemeId>(
    getStoredGalaxieTheme()
  );

  useEffect(() => {
    const handleThemeChange = (e: CustomEvent<{ themeId: GalaxieThemeId }>) => {
      setCurrentTheme(e.detail.themeId);
    };

    window.addEventListener(
      "galaxie-theme-change",
      handleThemeChange as EventListener
    );

    return () => {
      window.removeEventListener(
        "galaxie-theme-change",
        handleThemeChange as EventListener
      );
    };
  }, []);

  const handleThemeSelect = (themeId: GalaxieThemeId) => {
    applyGalaxieTheme(themeId);
    setCurrentTheme(themeId);
    onChange?.(themeId);
  };

  const themes = getAllGalaxieThemes();

  if (compact) {
    return (
      <div className="GalaxieThemePicker GalaxieThemePicker--compact">
        <div className="GalaxieThemePicker__swatches">
          {themes.map((theme) => (
            <button
              key={theme.id}
              className={`GalaxieThemePicker__swatch ${
                currentTheme === theme.id
                  ? "GalaxieThemePicker__swatch--active"
                  : ""
              }`}
              style={{
                background: `linear-gradient(135deg, ${theme.colors.primary}, ${theme.colors.secondary})`,
              }}
              onClick={() => handleThemeSelect(theme.id)}
              title={`${theme.name}: ${theme.description}`}
              aria-label={`Sélectionner le thème ${theme.name}`}
            >
              <span className="GalaxieThemePicker__swatch-icon">
                {theme.icon}
              </span>
            </button>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="GalaxieThemePicker">
      <h3 className="GalaxieThemePicker__title">Thème Galaxie</h3>
      <div className="GalaxieThemePicker__grid">
        {themes.map((theme) => (
          <button
            key={theme.id}
            className={`GalaxieThemePicker__card ${
              currentTheme === theme.id
                ? "GalaxieThemePicker__card--active"
                : ""
            }`}
            onClick={() => handleThemeSelect(theme.id)}
            aria-pressed={currentTheme === theme.id}
          >
            <div
              className="GalaxieThemePicker__preview"
              style={{
                background: theme.colors.background,
                borderColor: theme.colors.primary,
              }}
            >
              <div
                className="GalaxieThemePicker__preview-planet"
                style={{
                  background: `linear-gradient(135deg, ${theme.colors.primary}, ${theme.colors.secondary})`,
                  boxShadow: `0 0 15px ${theme.colors.primary}60`,
                }}
              />
              <div
                className="GalaxieThemePicker__preview-connection"
                style={{
                  background: theme.colors.secondary,
                }}
              />
              <div
                className="GalaxieThemePicker__preview-planet GalaxieThemePicker__preview-planet--small"
                style={{
                  background: `linear-gradient(135deg, ${theme.colors.accent}, ${theme.colors.primary})`,
                }}
              />
            </div>
            <div className="GalaxieThemePicker__info">
              <span className="GalaxieThemePicker__icon">{theme.icon}</span>
              <span className="GalaxieThemePicker__name">{theme.name}</span>
            </div>
            <p className="GalaxieThemePicker__description">
              {theme.description}
            </p>
          </button>
        ))}
      </div>
    </div>
  );
};

// Export pour utilisation dans le menu
export const GalaxieThemeMenuItem: React.FC = () => {
  return (
    <div className="GalaxieThemeMenuItem">
      <GalaxieThemePicker compact />
    </div>
  );
};
