export type GalaxieThemeId = keyof typeof GALAXIE_THEMES;

export interface GalaxieTheme {
  id: GalaxieThemeId;
  name: string;
  description: string;
  className: string;
  colors: {
    primary: string;
    secondary: string;
    accent: string;
    background: string;
  };
  icon: string;
}

const STORAGE_KEY = "galaxie-view-theme";
const DEFAULT_THEME: GalaxieThemeId = "nebula";

/**
 * Récupère le thème sauvegardé ou retourne le thème par défaut
 */
export const getStoredGalaxieTheme = (): GalaxieThemeId => {
  try {
    const stored = localStorage.getItem(STORAGE_KEY);
    if (stored && stored in GALAXIE_THEMES) {
      return stored as GalaxieThemeId;
    }
  } catch (e) {
    console.warn("Could not read Galaxie theme from storage:", e);
  }
  return DEFAULT_THEME;
};

/**
 * Sauvegarde le thème choisi
 */
export const setStoredGalaxieTheme = (themeId: GalaxieThemeId): void => {
  try {
    localStorage.setItem(STORAGE_KEY, themeId);
  } catch (e) {
    console.warn("Could not save Galaxie theme to storage:", e);
  }
};

/**
 * Applique un thème Galaxie View au document
 */
export const applyGalaxieTheme = (themeId: GalaxieThemeId): void => {
  const theme = GALAXIE_THEMES[themeId];
  if (!theme) {
    console.warn(`Unknown Galaxie theme: ${themeId}`);
    return;
  }

  // Supprimer les anciennes classes de thème
  const excalidrawElements = document.querySelectorAll(".excalidraw");
  excalidrawElements.forEach((el) => {
    Object.values(GALAXIE_THEMES).forEach((t) => {
      el.classList.remove(t.className);
    });
    el.classList.add(theme.className);
  });

  // Mettre à jour les variables CSS sur le root
  document.documentElement.style.setProperty(
    "--galaxie-current-theme",
    themeId
  );

  // Sauvegarder le choix
  setStoredGalaxieTheme(themeId);

  // Émettre un événement pour les composants qui écoutent
  window.dispatchEvent(
    new CustomEvent("galaxie-theme-change", {
      detail: { themeId, theme },
    })
  );
};

/**
 * Initialise le thème au chargement
 */
export const initGalaxieTheme = (): GalaxieThemeId => {
  const themeId = getStoredGalaxieTheme();
  applyGalaxieTheme(themeId);
  return themeId;
};

/**
 * Liste tous les thèmes disponibles
 */
export const getAllGalaxieThemes = (): GalaxieTheme[] => {
  return Object.values(GALAXIE_THEMES) as GalaxieTheme[];
};

/**
 * Récupère un thème par son ID
 */
export const getGalaxieTheme = (
  themeId: GalaxieThemeId
): GalaxieTheme | undefined => {
  return GALAXIE_THEMES[themeId] as GalaxieTheme | undefined;
};
